def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]

    # Find the full horizontal or vertical divider, excluding the background.
    lines = []
    for r, row in enumerate(grid):
        if len(set(row)) == 1 and row[0] != background:
            lines.append(("h", r, row[0]))
    for c in range(w):
        vals = [grid[r][c] for r in range(h)]
        if len(set(vals)) == 1 and vals[0] != background:
            lines.append(("v", c, vals[0]))
    if not lines:
        return [row[:] for row in grid]
    axis, divider, line_color = lines[0]
    obj = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
           if grid[r][c] != background and grid[r][c] != line_color]
    if not obj:
        return [row[:] for row in grid]

    out = [row[:] for row in grid]
    if axis == "h":
        minr = min(r for r, c, v in obj)
        maxr = max(r for r, c, v in obj)
        if maxr < divider:
            dr = divider - 1 - maxr
        elif minr > divider:
            dr = divider + 1 - minr
        else:
            dr = 0
        # Clear the original object, then place it against the divider.
        for r, c, v in obj:
            out[r][c] = background
        moved = [(r + dr, c, v) for r, c, v in obj]
        for r, c, v in moved:
            out[r][c] = v
        edge = min(r for r, c, v in moved) - 1 if maxr < divider else max(r for r, c, v in moved) + 1
        if 0 <= edge < h:
            out[edge] = [8] * w
    else:
        minc = min(c for r, c, v in obj)
        maxc = max(c for r, c, v in obj)
        if maxc < divider:
            dc = divider - 1 - maxc
        elif minc > divider:
            dc = divider + 1 - minc
        else:
            dc = 0
        for r, c, v in obj:
            out[r][c] = background
        moved = [(r, c + dc, v) for r, c, v in obj]
        for r, c, v in moved:
            out[r][c] = v
        edge = min(c for r, c, v in moved) - 1 if maxc < divider else max(c for r, c, v in moved) + 1
        if 0 <= edge < w:
            for r in range(h):
                out[r][edge] = 8
    return out
